ce','Plan routes and reduce expedition travel time.','travel_speed',15.00,35,35,1,501),(503,'recon',3,'Mapping','Reveal room threats with more starting intelligence.','intel_bonus',1.00,60,55,2,502),(504,'recon',4,'Signal triangulation','Coordinate expeditions through recovered radio signals.','travel_speed',25.00,90,80,3,503),(601,'defense',1,'Barricades','Reinforce entrances before the nightly horde arrives.','defense_bonus',4.00,20,20,1,NULL),(602,'defense',2,'Barbed wire','Slow infected at the perimeter.','defense_bonus',6.00,35,35,1,601),(603,'defense',3,'Motion detectors','Give defenders warning before a breach.','defense_bonus',9.00,60,55,2,602),(604,'defense',4,'Automated guns','Turn recovered machinery into perimeter firepower.','defense_bonus',14.00,90,80,3,603),(701,'energy',1,'Batteries','Store enough power to smooth out generator output.','power_bonus',2.00,20,20,1,NULL),(702,'energy',2,'Combustion engine','Improve fuel use and generator reliability.','petrol_rate',15.00,35,35,1,701),(703,'energy',3,'Power network','Distribute electricity efficiently across the compound.','power_bonus',4.00,60,55,2,702),(704,'energy',4,'Wind power','Supplement the generators with renewable power.','power_bonus',7.00,90,80,3,703);
